**Function**: number_to_string

```c
// C program for the function called number_to_string
// Contains target function implementation and dependency signatures

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Target function implementation
int number_to_string(uint8_t *number, uint8_t N, char *out_str, size_t out_str_len)
{
    if (number == NULL || out_str == NULL || N == 0 || out_str_len == 0)
    {
        return -1;
    }

    uint8_t start_pos = N - 1;

    /* Skip leading zeros */
    while (start_pos > 0 && number[start_pos] == 0) start_pos--;

    size_t num_digits = start_pos + 1;
    if (num_digits >= out_str_len)
    {
        return -1;  /* Output buffer too small */
    }

    size_t out_idx = 0;
    for (int i = start_pos; i >= 0; i--)
    {
        out_str[out_idx++] = number[i] + '0';
    }
    out_str[out_idx] = '\0';

    return 0;
}

```

